'use strict';
(() => {
  const $=id=>document.getElementById(id);
  const incoming=new URLSearchParams(location.hash.slice(1)).get('token');
  const storageKey=`optdsh-uninstaller-token:${location.origin}`;
  let token=incoming||'';
  try{if(incoming)sessionStorage.setItem(storageKey,incoming);else token=sessionStorage.getItem(storageKey)||'';}catch{/* 本次会话仍可使用URL凭据。 */}
  history.replaceState(null,'',location.pathname+location.search);
  let info,plan,step=0,busy=false,timer,lastStatus;
  const titles=['选择这次要卸载的内容','核对路径与卸载影响','正在卸载所选内容','所选项目完成，资料已保留'];
  const intros=['逐项核对实际位置，只处理你勾选的内容。','请先结束正在运行的任务，再确认卸载。','当前动作与详细日志会持续更新。','用户资料和课题文件保留在原位置。'];
  async function api(path,body){const response=await fetch(path,{method:body===undefined?'GET':'POST',headers:{'Content-Type':'application/json','X-Installer-Token':token},...(body===undefined?{}:{body:JSON.stringify(body)})});let result;try{result=await response.json();}catch{throw new Error(`卸载服务返回了无效响应（${response.status}）。`);}if(!response.ok||(result.error&&!result.state))throw new Error(typeof result.error==='string'?result.error:result.error?.message||`请求失败（${response.status}）。`);return result;}
  function notice(message){$('notice').textContent=message||'';$('notice').hidden=!message;if(message)requestAnimationFrame(()=>$('notice').scrollIntoView({block:'center'}));}
  function selection(){return {items:[...document.querySelectorAll('#items input:checked')].map(input=>input.value)};}
  function list(node,items){node.replaceChildren();for(const item of items||[]){const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=item.label;dd.textContent=item.path||'未提供路径';node.append(dt,dd);if(item.description){const description=document.createElement('p');description.className='item-detail';description.textContent=item.description;dd.append(description);}}}
  function render(){document.querySelectorAll('.steps li').forEach((li,i)=>{li.classList.toggle('current',i===step);li.classList.toggle('done',i<step);if(i===step)li.setAttribute('aria-current','step');else li.removeAttribute('aria-current');});$('step-label').textContent=`第 ${step+1} 步 / 共 4 步`;$('heading').textContent=titles[step];$('intro').textContent=intros[step];['selection-panel','review-panel','progress-panel','complete-panel'].forEach((id,i)=>$(id).hidden=i!==step);$('back').hidden=step!==1;$('back').disabled=busy;$('primary').textContent=step===2?'正在卸载…':busy?'正在处理…':['核对卸载影响','确认卸载所选项目','','复制卸载结果'][step];$('primary').disabled=!info||busy||step===2||(step===0&&!selection().items.length);$('primary').classList.toggle('danger',step===1);$('action-note').textContent=['核对影响前不会执行卸载。','仅处理上方明确列出的项目。','请保持窗口打开。','可以关闭此窗口，资料仍在原位置。'][step];}
  function warnings(messages){$('warnings').replaceChildren();for(const message of messages||[]){const p=document.createElement('p');p.className='warning-box';p.textContent=message;$('warnings').append(p);}}
  function stopPoll(){if(timer)clearTimeout(timer);timer=undefined;}
  async function copy(text,button){try{await navigator.clipboard.writeText(text);button.textContent='已复制';}catch{notice('无法自动复制，请在日志或卸载结果中选择文字复制。');}}
  async function poll(){stopPoll();try{const status=await api('/api/status');lastStatus=status;$('phase').textContent=status.phase||'正在执行卸载';$('logs').textContent=(status.log||[]).join('\n');$('log-count').textContent=status.log?.length?`（${status.log.length} 条）`:'';if($('log-details').open)$('logs').scrollTop=$('logs').scrollHeight;if(status.state==='succeeded'){step=3;busy=false;const receipt=status.receipt||{};const selected=plan?.selected||receipt.selected||receipt.items||[];list($('completed-items'),Array.isArray(selected)?selected.filter(item=>typeof item==='object'):[]);$('receipt').textContent=JSON.stringify(receipt,null,2);render();notice('');return;}if(status.state==='failed'){step=2;busy=false;render();$('spinner').hidden=true;$('progress-bar').hidden=true;$('phase').textContent='卸载未完成';$('phase-description').textContent='诊断信息已保留，请查看原因后返回核对。';$('log-details').open=true;notice(status.error||'卸载失败，请查看详细日志。');$('primary').disabled=false;$('primary').textContent='返回选择并重试';return;}if(status.state==='uninstalling'){step=2;render();timer=setTimeout(poll,1000);}}catch(error){notice(`暂时无法读取卸载进展：${error.message}\n正在重试连接，请保持窗口打开。`);timer=setTimeout(poll,2000);}}
  $('items').addEventListener('change',()=>{plan=undefined;render();});
  $('back').addEventListener('click',()=>{step=0;notice('');render();});
  $('primary').addEventListener('click',async()=>{if(busy)return;notice('');if(step===0){if(!selection().items.length)return;busy=true;render();try{plan=await api('/api/plan',selection());list($('selected-review'),plan.selected);if(plan.preserved)list($('preserved'),plan.preserved);warnings(plan.warnings);step=1;}catch(error){notice(error.message);}finally{busy=false;render();}return;}if(step===1){if(!plan){step=0;render();notice('卸载选择已变化，请重新核对。');return;}busy=true;render();try{await api('/api/uninstall',selection());step=2;$('spinner').hidden=false;$('progress-bar').hidden=false;render();poll();}catch(error){busy=false;notice(error.message);render();}return;}if(step===2&&lastStatus?.state==='failed'){step=0;plan=undefined;render();return;}if(step===3)await copy(['optDSH 卸载结果',JSON.stringify(lastStatus?.receipt||{},null,2),'用户资料保留：',...(info?.preserved||[]).map(item=>`${item.label}: ${item.path}`)].join('\n'),$('primary'));});
  $('copy-logs').addEventListener('click',()=>copy([lastStatus?.error,...(lastStatus?.log||[])].filter(Boolean).join('\n'),$('copy-logs')));
  window.addEventListener('pagehide',stopPoll);
  async function init(){if(!token){notice('缺少卸载会话凭据。请从已安装目录中的图形卸载入口重新打开。');$('primary').textContent='请从卸载入口打开';return;}try{info=await api('/api/info');$('version').textContent=info.version||'已安装版本';for(const item of info.items||[]){const label=document.createElement('label');label.className='component remove-item';const input=document.createElement('input');input.type='checkbox';input.value=item.id;input.checked=Boolean(item.default);const content=document.createElement('span'),title=document.createElement('strong'),path=document.createElement('code'),description=document.createElement('small');title.textContent=item.label;path.textContent=item.path||'未提供路径';description.textContent=item.description||'';content.append(title,path,description);label.append(input,content);$('items').append(label);}list($('preserved'),info.preserved);render();const status=await api('/api/status');if(['uninstalling','succeeded','failed'].includes(status.state))await poll();}catch(error){notice(error.message);$('primary').textContent='无法读取安装信息';}}
  init();
})();
